async function listFiles(env,a,t,i,key){let e=await own(env,a,t,i),sql='SELECT id,question_key,file_name,content_type,size_bytes,created_at FROM briefing_files WHERE client_id=? AND scope_type=? AND scope_id=? AND active=1',params=[e.client_id,t,i];if(key){sql+=' AND question_key=?';params.push(key)}sql+=' ORDER BY created_at DESC';let r=await env.DB.prepare(sql).bind(...params).all();return{files:r.results}}
async function uploadFile(env,a,b){let t=String(b.type||'').toUpperCase(),e=await own(env,a,t,b.id),q=await env.DB.prepare('SELECT allow_files FROM form_questions WHERE template_id=? AND question_key=? AND active=1').bind(e.template_id,b.key).first();if(!q||!q.allow_files)throw Object.assign(new Error('files_not_allowed'),{status:400});let data=String(b.data_base64||'').replace(/^data:[^,]*,/,''),bytes=Math.floor(data.length*3/4);if(!data||bytes>5*1024*1024)throw Object.assign(new Error('file_too_large'),{status:413});let fid=id(),ac=actorOf(a),ts=now(),name=String(b.file_name||'arquivo').slice(0,180),ctype=String(b.content_type||'application/octet-stream').slice(0,100),chunks=[];for(let pos=0,n=0;pos<data.length;pos+=500000,n++)chunks.push(env.DB.prepare('INSERT INTO briefing_file_chunks(file_id,chunk_no,data_b64) VALUES(?,?,?)').bind(fid,n,data.slice(pos,pos+500000)));await env.DB.prepare('INSERT INTO briefing_files(id,client_id,scope_type,scope_id,question_key,file_name,content_type,size_bytes,storage_provider,storage_key,active,uploaded_by_type,uploaded_by_id,uploaded_by_name,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(fid,e.client_id,t,b.id,b.key,name,ctype,Number(b.size_bytes)||bytes,'D1_CHUNKED',fid,1,a.kind,ac.id,ac.name,ts).run();if(chunks.length)await env.DB.batch(chunks);return{ok:true,file:{id:fid,question_key:b.key,file_name:name,content_type:ctype,size_bytes:Number(b.size_bytes)||bytes,created_at:ts}}}
async function deleteFile(env,a,fid){let f=await env.DB.prepare('SELECT * FROM briefing_files WHERE id=? AND active=1').bind(fid).first();if(!f)throw Object.assign(new Error('not_found'),{status:404});if(a.kind==='CLIENT'&&f.client_id!==a.client_id)throw Object.assign(new Error('forbidden'),{status:403});await env.DB.prepare('UPDATE briefing_files SET active=0 WHERE id=?').bind(fid).run();return{ok:true}}
