async function portalSupabase(env,r,u,a){let sub=u.pathname.slice('/api/client'.length),supported=new Set(['/overview','/entity','/answer','/history','/products','/personas','/link-persona','/duplicate-persona','/context','/progress','/review-flag','/review','/submit','/account','/portal-history']);if(!supported.has(sub)||!a.sb_access_token)return null;let payload=(r.method==='GET'||r.method==='HEAD')?null:await r.text(),call=()=>fetch(SB+'/functions/v1/briefing-client-api'+sub+u.search,{method:r.method,headers:{apikey:KEY,Authorization:'Bearer '+a.sb_access_token,'content-type':'application/json'},body:payload});let x=await call();if(x.status===401&&await refreshClientSupabase(env,a))x=await call();let txt=await x.text();if(x.ok&&(sub==='/overview'||sub==='/account'))try{let o=JSON.parse(txt);if(sub==='/overview')o.user={display_name:a.display_name||a.username||'',client_name:a.client_name||''};if(sub==='/account'&&o.client&&!o.client.name)o.client.name=a.client_name||'';txt=JSON.stringify(o)}catch{}return new Response(txt,{status:x.status,headers:{'content-type':x.headers.get('content-type')||'application/json','cache-control':'no-store'}})}

