function pdfValue(v){return Array.isArray(v)?v.join(', '):v&&typeof v==='object'?JSON.stringify(v):String(v??'')}
function pdfSafe(v){return String(v??'').replace(/[–—]/g,'-').replace(/[“”]/g,'\"').replace(/[•·]/g,'-').replace(/[^\x20-\x7EÀ-ÿ\n]/g,'')}
function pdfByte(v){return pdfSafe(v).replace(/[^\x20-\x7E\xA0-\xFF]/g,'?')}
function pdfEsc(v){return pdfByte(v).replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)')}
function pdfSlug(v){return pdfSafe(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,80)||'sem-nome'}
function pdfWrap(v,max){let words=pdfSafe(v).replace(/\s+/g,' ').trim().split(' '),lines=[],line='';for(let word of words){if(word.length>max){if(line){lines.push(line);line=''}for(let i=0;i<word.length;i+=max)lines.push(word.slice(i,i+max));continue}let next=line?line+' '+word:word;if(next.length>max){if(line)lines.push(line);line=word}else line=next}if(line)lines.push(line);return lines.length?lines:['-']}
function pdfText(x,y,size,value,bold,color){return 'BT /'+(bold?'F2':'F1')+' '+size+' Tf '+(color||'0.09 0.12 0.16')+' rg 1 0 0 1 '+x+' '+(842-y)+' Tm ('+pdfEsc(value)+') Tj ET\n'}
function pdfBytes(pages){let objects=[],pageIds=[];objects[1]='<< /Type /Catalog /Pages 2 0 R >>';objects[3]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>';objects[4]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>';for(let i=0;i<pages.length;i++){let pageId=5+i*2,contentId=6+i*2,ops=pages[i];pageIds.push(pageId+' 0 R');objects[pageId]='<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents '+contentId+' 0 R >>';objects[contentId]='<< /Length '+ops.length+' >>\nstream\n'+ops+'endstream'}objects[2]='<< /Type /Pages /Count '+pages.length+' /Kids ['+pageIds.join(' ')+'] >>';let out='%PDF-1.4\n%\xE2\xE3\xCF\xD3\n',offsets=[0];for(let i=1;i<objects.length;i++){offsets[i]=out.length;out+=i+' 0 obj\n'+objects[i]+'\nendobj\n'}let xref=out.length;out+='xref\n0 '+objects.length+'\n0000000000 65535 f \n';for(let i=1;i<objects.length;i++)out+=String(offsets[i]).padStart(10,'0')+' 00000 n \n';out+='trailer\n<< /Size '+objects.length+' /Root 1 0 R >>\nstartxref\n'+xref+'\n%%EOF';let bytes=new Uint8Array(out.length);for(let i=0;i<out.length;i++)bytes[i]=out.charCodeAt(i)&255;return bytes}
function briefingPdfResponse(b,type){let kind=type==='PERSONA'?'PERSONA':'PRODUCT',name=b.entity?.name||'Sem nome',kindLabel=kind==='PRODUCT'?'BRIEFING DE PRODUTO':'BRIEFING DE PERSONA',groups={},pages=[],page=null,y=126,generated=new Date().toLocaleString('pt-BR');for(let q of b.questions||[])(groups[q.section_name||'Informações gerais']??=[]).push(q);function header(){page+='0.03 0.05 0.08 rg 0 750 595 92 re f\n1 0.35 0.11 rg 0 750 8 92 re f\n'+pdfText(44,34,10,'LEONARDO IMOBI / BRIEFING HUB',true,'1 1 1')+pdfText(44,53,8,'Documento gerado em '+generated,false,'0.72 0.78 0.84')+pdfText(44,69,8,'Fonte oficial: informações registradas no portal do cliente',false,'0.58 0.66 0.73')}function footer(){page+='0.85 0.88 0.91 RG 44 32 m 551 32 l S\n'+pdfText(44,824,7.5,name,false,'0.42 0.48 0.54')+pdfText(510,824,7.5,'Briefing Hub',false,'0.42 0.48 0.54')}function newPage(){if(page!==null){footer();pages.push(page)}page='';y=126;header()}function need(h){if(y+h>790)newPage()}newPage();page+=pdfText(44,y,10,kindLabel,true,'0.07 0.27 0.42');y+=25;for(let line of pdfWrap(name,38)){page+=pdfText(44,y,24,line,true);y+=28}y+=4;page+=pdfText(44,y,9,'Nome do '+(kind==='PRODUCT'?'produto / empreendimento':'perfil')+': '+name,false,'0.36 0.42 0.48');y+=31;let answered=0;for(let section of Object.keys(groups)){let rows=[];for(let q of groups[section]){let value=b.answers?.[q.question_key]?.value;if(!filled(value))continue;rows.push([q.label,pdfValue(value)]);answered++}if(!rows.length)continue;need(43);page+='0.93 0.96 0.98 rg 44 '+(842-y-14)+' 507 27 re f\n'+pdfText(56,y+3,10,pdfSafe(section).toUpperCase(),true,'0.07 0.27 0.42');y+=32;for(let row of rows){let labels=pdfWrap(row[0],92),values=pdfWrap(row[1],90),block=labels.length*10+values.length*13+15;need(block);for(let line of labels){page+=pdfText(44,y,8,line,true,'0.36 0.42 0.48');y+=10}y+=3;for(let line of values){page+=pdfText(44,y,9.5,line,false);y+=13}y+=12}}if(!answered)page+=pdfText(44,y,10,'Nenhuma resposta foi registrada neste briefing.',false,'0.36 0.42 0.48');footer();pages.push(page);let filename='briefing-'+(kind==='PRODUCT'?'produto-':'persona-')+pdfSlug(name)+'.pdf';return new Response(pdfBytes(pages),{headers:{'content-type':'application/pdf','content-disposition':'attachment; filename="'+filename+'"','cache-control':'private, no-store','x-content-type-options':'nosniff'}})}
async function crmVaultKey(env){let secret=String(env.CRM_VAULT_SECRET||'');if(!secret)throw Object.assign(new Error('vault_unavailable'),{status:503});let h=await crypto.subtle.digest('SHA-256',enc.encode(secret));return crypto.subtle.importKey('raw',h,{name:'AES-GCM'},false,['encrypt','decrypt'])}
async function sealCrmSecret(env,text){text=String(text||'');if(!text)return null;let key=await crmVaultKey(env),iv=crypto.getRandomValues(new Uint8Array(12)),ct=await crypto.subtle.encrypt({name:'AES-GCM',iv:iv},key,enc.encode(text));return b64(iv)+'.'+b64(ct)}
async function openCrmSecret(env,sealed){if(!sealed)return null;let parts=String(sealed).split('.');if(parts.length!==2)return null;try{let key=await crmVaultKey(env),pt=await crypto.subtle.decrypt({name:'AES-GCM',iv:ub(parts[0])},key,ub(parts[1]));return new TextDecoder().decode(pt)}catch{return null}}
function canRevealCrm(a){return ['MGMT','ADMIN','OWNER','OPS','TECH','DEV'].includes(String(a&&a.staff_role||'').toUpperCase())}
