async function readPortalConfig(env,clientId,reveal){let x=await env.DB.prepare('SELECT * FROM client_portal_config WHERE client_id=?').bind(clientId).first();let config={drive_url:x&&x.drive_url||'',has_crm:x&&x.has_crm!=null?!!Number(x.has_crm):null,crm_name:x&&x.crm_name||'',crm_url:x&&x.crm_url||'',crm_login:x&&x.crm_login||'',crm_password_saved:!!(x&&x.crm_secret_enc),lead_phone:x&&x.lead_phone||'',updated_at:x&&x.updated_at||null};if(reveal&&x&&x.crm_secret_enc)config.crm_password=await openCrmSecret(env,x.crm_secret_enc);return config}
