async function driveBridge(env,a,action,payload={}){if(!env.DRIVE_BRIDGE_URL||!env.DRIVE_BRIDGE_KEY)throw Object.assign(new Error('drive_bridge_not_configured'),{status:503});let rr=await fetch(String(env.DRIVE_BRIDGE_URL),{method:'POST',headers:{'content-type':'text/plain;charset=UTF-8','cache-control':'no-store'},body:JSON.stringify({bridge_key:String(env.DRIVE_BRIDGE_KEY),action,client_id:a.client_id,client_name:a.client_name||'',...payload}),redirect:'follow'}),txt=await rr.text(),x;try{x=JSON.parse(txt)}catch{x={ok:false,error:'drive_bridge_invalid_response'}}if(!rr.ok||!x.ok)throw Object.assign(new Error(x.error||('drive_bridge_http_'+rr.status)),{status:x.status||502,details:x});return x}
