function identityInitials(a){let n=String(a&&a.client_name||a&&a.display_name||a&&a.username||'BH').trim(),p=n.split(/\s+/).filter(Boolean);return(p.length>1?(p[0][0]+p[p.length-1][0]):p[0].slice(0,2)).toUpperCase()}
function identityFile(files){let all=(Array.isArray(files)?files:[]).map(f=>{let name=String(f.file_name||f.name||'').toLowerCase(),type=String(f.content_type||f.mime_type||'').toLowerCase(),url=f.thumbnail_url||f.thumbnailLink||f.download_url||f.url||f.web_url||'';if(!/^https?:\/\//i.test(String(url))||(!type.startsWith('image/')&&!/\.(png|jpe?g|webp|gif|svg)$/i.test(name)))return null;let score=0,fit='cover';if(/logo|logotipo|marca|brand|identidade|identidade visual/.test(name)){score=100;fit='contain'}else if(/avatar|perfil|profile|foto.{0,12}(pessoal|corretor|corretora|responsavel)/.test(name)){score=80;fit='cover'}else return null;if(/im[oó]vel|empreendimento|fachada|apartamento|interior|planta|tour|video/.test(name))score-=1000;return score>0?{image_url:String(url),source:fit==='contain'?'DRIVE_LOGO':'DRIVE_PROFILE',fit,score}:null}).filter(Boolean);all.sort((a,b)=>b.score-a.score);return all[0]||null}
async function clientIdentity(env,a){let ts=now(),cache=await env.DB.prepare("SELECT image_url,source,fit,expires_at FROM client_identity_cache WHERE client_id=?").bind(a.client_id).first();if(cache&&cache.expires_at>ts)return{image_url:cache.image_url||null,source:cache.source,fit:cache.fit,cached:true};let found=null;try{let files=await driveBridge(env,a,'list',{});found=identityFile(files.files)}catch{}if(!found&&a.sb_access_token){try{let rr=await fetch(IDENTITY+'?client_id='+encodeURIComponent(a.client_id),{headers:{Authorization:'Bearer '+a.sb_access_token,apikey:KEY},signal:AbortSignal.timeout(18000)}),x=await rr.json().catch(()=>({}));if(rr.ok&&x&&/^https:\/\//i.test(String(x.image_url||'')))found={image_url:x.image_url,source:'WHATSAPP_GROUP',fit:'cover'}}catch{}}let out=found||{image_url:null,source:'INITIALS',fit:'cover'},exp=new Date(Date.now()+(found?6:1)*60*60*1000).toISOString();await env.DB.prepare("INSERT INTO client_identity_cache(client_id,image_url,source,fit,updated_at,expires_at) VALUES(?,?,?,?,?,?) ON CONFLICT(client_id) DO UPDATE SET image_url=excluded.image_url,source=excluded.source,fit=excluded.fit,updated_at=excluded.updated_at,expires_at=excluded.expires_at").bind(a.client_id,out.image_url,out.source,out.fit,ts,exp).run();return out}

