async function uploadPortalMaterialChunk(env,a,r,u){let sid=String(u.searchParams.get('upload_id')||''),start=Number(u.searchParams.get('start')),end=Number(u.searchParams.get('end')),total=Number(u.searchParams.get('total'));if(!sid||!Number.isInteger(start)||!Number.isInteger(end)||!Number.isInteger(total)||start<0||end<start||total<=end)throw Object.assign(new Error('invalid_upload_chunk'),{status:400});let s=await env.DB.prepare('SELECT * FROM drive_upload_sessions WHERE id=? AND client_id=?').bind(sid,a.client_id).first();if(!s)throw Object.assign(new Error('upload_session_not_found'),{status:404});if(total!==Number(s.size_bytes))throw Object.assign(new Error('upload_size_mismatch'),{status:400});let body=await r.arrayBuffer();if(body.byteLength!==end-start+1)throw Object.assign(new Error('upload_chunk_size_mismatch'),{status:400});let up=await fetch(s.session_url,{method:'PUT',headers:{'content-type':s.content_type,'content-range':'bytes '+start+'-'+end+'/'+total},body});if(!up.ok&&up.status!==308)throw Object.assign(new Error('drive_upload_failed'),{status:502,details:{upstream_status:up.status}});let done=end+1===total&&up.status!==308,ts=now();if(done)await env.DB.prepare('DELETE FROM drive_upload_sessions WHERE id=?').bind(sid).run();else await env.DB.prepare('UPDATE drive_upload_sessions SET updated_at=? WHERE id=?').bind(ts,sid).run();return{ok:true,done,next_byte:end+1,upstream_status:up.status}}
