 view.innerHTML='<div class="v2-fade"><div class="v2-eyebrow">Estratégia do briefing</div><h2>Visão estratégica viva</h2><p class="muted">Resumo, origem das informações e relações reais entre produtos e Personas.</p><h3 style="margin-top:22px">Mapa Produto × Persona</h3><p class="muted">Os vínculos abaixo são os mesmos cadastrados no briefing.</p>'+map+'<h3 style="margin-top:22px">Abrir resumo estratégico</h3><div class="project-actions">'+controls+'</div></div>';
