async function newEntityClient(type,productId){let isP=type==='PRODUCT',m=modal('<div class="v2-eyebrow">Novo '+(isP?'produto':'perfil')+'</div><h2>'+(isP?'Qual produto vamos trabalhar?':'Como você quer chamar esta Persona?')+'</h2><form id="v2new" class="grid"><label>'+(isP?'Nome do produto / empreendimento':'Nome interno da Persona')+'<input name="name" required autofocus></label><div class="row"><button class="btn primary">Criar e começar</button><button type="button" class="btn" id="v2cancel">Cancelar</button></div></form>');$('#v2cancel',m).onclick=()=>m.remove();$('#v2new',m).onsubmit=async e=>{e.preventDefault();let name=new FormData(e.target).get('name'),r=await A('/api/client/'+(isP?'products':'personas'),{method:'POST',body:JSON.stringify({name})});invalidateClientCache();if(productId&&!isP)await A('/api/client/link-persona',{method:'POST',body:JSON.stringify({product_id:productId,persona_id:r.id})});m.remove();briefingMode(type,r.id,{})}}
